 if(n==='plan_building'){ rcOpen(); const B=RC.b; m.type='building'; if(a.footprint){ const P=ll(a.footprint); if(P.length<3)return 'footprint needs 3 or more [lat,lon] corners'; Object.assign(B,{fp:P,name:'',obs:[],hSrc:''}); } else if(isFinite(+a.lat)&&isFinite(+a.lon)){ const o=await rcBldPick([+a.lat,+a.lon]); if(o.err)return o.err; try{ gmGo(+a.lat,+a.lon,18); }catch(e){} } if(a.height_m>0){ B.h=+a.height_m; B.hSrc=b2('given in the request: confirm on site','من الطلب: أكّده في الموقع'); } [['facade_gsd_cm','gsd'],['roof_gsd_cm','gsdRoof'],['rings','rings'],['min_distance_m','minDist'],['hour','hr']].forEach(k=>{ if(a[k[0]]!=null&&isFinite(+a[k[0]]))B[k[1]]=+a[k[0]]; }); if(a.date)B.date=String(a.date).slice(0,10); if(a.takeoff){ const P=ll([a.takeoff]); if(P.length)B.takeoff=P[0]; } if(a.wind_ms!=null)B.wind={spd:+a.wind_ms,gust:'',dir:a.wind_from_deg==null?'':+a.wind_from_deg,src:''}; if(a.fetch_wind)await rcWindFetch(); const p=rcPlan(); if(p.err){ RCB.err=p.err; rcMisPanel(); return p.err; } RCB.err=''; rcMisPanel(); return {building:{name:B.name,height:p.b.h,heightSource:B.hSrc,obstacles:B.obs.length},roof:p.b.roof,rings:p.b.rings.map(r=>({height:r.z,pitch:r.pitch,shots:r.shots,gsdCm:r.gsdCm})),ringRadius:p.b.R,standOff:p.b.D,totalShots:p.stats.photos,timeMin:p.stats.timeMin,batteries:p.stats.batteries,sun:B.sun?{azimuth:B.sun.sun.az,elevation:B.sun.sun.el,roofWindow:B.sun.nadirWin,facadesInShadow:B.sun.facades.filter(f=>!f.lit).map(f=>f.az)}:null,wind:B.windR?{speed:B.windR.spd,from:B.windR.dir,bestLegHeading:B.windR.bestAz,timeWorstCase:B.windR.timeWind}:null,lineOfSight:B.los,warnings:p.warns.map(w=>w[0]+': '+w[2])}; }
 if(n==='import_survey_file'){ rcOpen(); if(a.text==null||a.text===''){ XC.rc_imp.run(); return 'file picker opened for the user'; } const r=rcImportText(a.name||'points.csv',String(a.text),{order:a.order}); RCB.last=r; RC.tab='imp'; rcDatPanel(); rcZoomData(); return r; }
