 if((on||fl)&&/(contour|كنتور)/.test(s)){ const iv=num(/(\d+(?:\.\d+)?)/)||1; rcTool('make_contours',{interval:iv}).then(r=>say2(typeof r==='string'?r:b2('Contours every '+r.interval+' m: '+r.segments+' segments, '+r.levels.length+' levels.','كنتور كل '+r.interval+' م: '+r.segments+' قطعة، '+r.levels.length+' منسوب.'),'a')).catch(e=>say2(e.message,'a')); return true; }
